// Headless end-to-end checks of the engine against real media generated by ffmpeg.
#include "core/effectdefs.h"
#include "core/mediacache.h"
#include "core/ops.h"
#include "engine/audiomix.h"
#include "engine/compositor.h"
#include "engine/exporter.h"
#include "engine/imagefx.h"
#include <QElapsedTimer>
#include <QEventLoop>
#include <QFileInfo>
#include <QGuiApplication>
#include <QJsonDocument>
#include <QProcess>
#include <QTemporaryDir>
#include <QThread>
#include <cmath>
#include <cstdio>

static int fails = 0;
#define CHECK(c) do { if (!(c)) { printf("FAIL line %d: %s\n", __LINE__, #c); ++fails; } else printf("ok   %s\n", #c); fflush(stdout); } while (0)

static bool gen(const QString &out, const QStringList &a)
{
    QStringList args{"-hide_banner", "-loglevel", "error", "-y"};
    args << a << out;
    return QProcess::execute(CACHE->ffmpeg(), args) == 0;
}
static void pump(int ms)
{
    QElapsedTimer t;
    t.start();
    while (t.elapsed() < ms) { QCoreApplication::processEvents(QEventLoop::AllEvents, 20); QThread::msleep(5); }
}

int main(int argc, char **argv)
{
    QGuiApplication app(argc, argv);
    QTemporaryDir dir;
    CHECK(CACHE->available());
    // A clip whose brightness encodes the frame number makes frame accuracy directly measurable.
    QString v = dir.filePath("ramp.mp4");
    CHECK(gen(v, {"-f", "lavfi", "-i", "color=c=black:s=320x180:r=30:d=4", "-f", "lavfi", "-i", "sine=f=440:r=48000:d=4",
                  "-vf", "geq=lum='min(235,16+N*2)':cb=128:cr=128", "-c:v", "libx264", "-g", "30", "-crf", "1", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest"}));
    MediaItem m;
    CHECK(CACHE->probe(v, m));
    CHECK(m.hasVideo && m.hasAudio && m.w == 320 && m.h == 180);
    CHECK(std::fabs(m.fps - 30) < .01);
    m.id = 1;

    // --- random-access frame accuracy
    {
        VideoReader r(v, 320, 180, 30, false);
        for (Frame n : {Frame(0), Frame(5), Frame(50), Frame(49), Frame(10), Frame(100), Frame(101), Frame(60)}) {
            QImage i = r.get(n, 8000);
            int g = i.isNull() ? -1 : qGray(i.pixel(160, 90));
            double expected = (qMin(235.0, 16.0 + n * 2) - 16) * 255.0 / 219.0;
            printf("frame %lld gray %d expected %.0f\n", (long long)n, g, expected);
            CHECK(std::fabs(g - expected) <= 4);
        }
    }

    // --- model ops
    ProjectState st;
    st.nextId = 10;
    st.media << m;
    Sequence q; q.id = 2; q.w = 320; q.h = 180; q.fpsNum = 30;
    for (int i = 0; i < 2; ++i) Ops::addTrack(st, q, TrackType::Video);
    for (int i = 0; i < 2; ++i) Ops::addTrack(st, q, TrackType::Audio);
    Ops::Patch p{0, 0};
    Ops::overwriteMedia(st, q, m, 0, 2, 0, p);
    CHECK(q.video[0].clips.size() == 1 && q.audio[0].clips.size() == 1);
    CHECK(q.video[0].clips[0].dur == 60);
    CHECK(q.video[0].clips[0].link != 0 && q.video[0].clips[0].link == q.audio[0].clips[0].link);
    Ops::razor(st, q, 30, {});
    CHECK(q.video[0].clips.size() == 2);
    CHECK(q.video[0].clips[1].start == 30);
    CHECK(std::fabs(q.video[0].clips[1].srcIn - 1.0) < 1e-6);
    CHECK(q.video[0].clips[0].dur == 30);
    Ops::insertMedia(st, q, m, 0, 1, 30, p);
    CHECK(q.video[0].clips.size() == 3);
    CHECK(q.duration() == 90);
    QSet<int> del{q.video[0].clips[1].id};
    Ops::deleteClips(q, del, true);
    CHECK(q.video[0].clips.size() == 2 && q.video[0].clips[1].start == 30);
    Ops::clearRange(q, q.video[0], 10, 20, &st);
    CHECK(q.video[0].clips.size() == 3);
    CHECK(q.video[0].clips[1].start == 20 && std::fabs(q.video[0].clips[1].srcIn - 20.0 / 30) < 1e-6);
    q.video[0].clips.clear(); q.audio[0].clips.clear(); q.audio[0].transitions.clear();
    Ops::overwriteMedia(st, q, m, 0, 2, 0, p);
    st.seqs << q;

    // --- JSON round trip
    {
        auto j = stateToJson(st);
        auto r = stateFromJson(QJsonDocument::fromJson(QJsonDocument(j).toJson()).object());
        CHECK(r.seqs.size() == 1 && r.seqs[0].video[0].clips[0].fx.size() == 2);
        CHECK(stateToJson(r) == j);
    }

    // --- compositor: frame content, opacity, effect
    Compositor comp;
    {
        QImage a = comp.render(st, 2, 45, 1.0, true);
        int g = qGray(a.pixel(160, 90));
        printf("composite gray %d\n", g);
        CHECK(a.width() == 320 && std::fabs(g - 90 * 255.0 / 219) <= 5);
        auto *c = &st.seqs[0].video[0].clips[0];
        c->effect("opacity")->find("opacity")->value = 50;
        QImage b = comp.render(st, 2, 45, 1.0, true);
        CHECK(std::fabs(qGray(b.pixel(160, 90)) - g / 2.0) <= 3);
        c->effect("opacity")->find("opacity")->value = 100;
        c->fx << EffectRegistry::make("invert");
        QImage d = comp.render(st, 2, 45, 1.0, true);
        CHECK(std::fabs(qGray(d.pixel(160, 90)) - (255 - g)) <= 3);
        c->fx.removeLast();
        // half resolution
        CHECK(comp.render(st, 2, 45, .5, true).width() == 160);
        // keyframed scale moves pixels off the corner
        auto *sc = c->effect("motion")->find("scale");
        sc->animated = true; sc->setKey(0, 100); sc->setKey(59, 50);
        CHECK(std::fabs(sc->at(30) - 74.576) < .1);
        QImage e = comp.render(st, 2, 59, 1.0, true);
        CHECK(qGray(e.pixel(2, 2)) == 0);
        sc->animated = false; sc->keys.clear();
    }

    // --- every registered video effect runs and leaves a valid frame
    for (auto &d : EffectRegistry::all()) {
        if (d.audio || d.intrinsic) continue;
        QImage i(64, 64, QImage::Format_ARGB32_Premultiplied); i.fill(0xFF808040);
        ImageFx::Ctx c;
        ImageFx::apply(EffectRegistry::make(d.id), i, c);
        if (i.isNull() || i.width() != 64) { printf("bad effect %s\n", qPrintable(d.id)); ++fails; }
    }
    // --- every transition renders
    {
        ProjectState s2 = st;
        Ops::razor(s2, s2.seqs[0], 30, {});
        for (auto &td : EffectRegistry::transitions()) {
            if (td.audio) continue;
            s2.seqs[0].video[0].transitions.clear();
            Ops::addTransition(s2.seqs[0].video[0], td.id, 30, 20, .5);
            QImage i = comp.render(s2, 2, 30, .5, true);
            if (i.isNull()) { printf("bad transition %s\n", qPrintable(td.id)); ++fails; }
        }
    }

    // --- audio: conform, peaks, mix level and mute
    CACHE->ensureAudio(v);
    for (int i = 0; i < 400 && !CACHE->pcm(v).data; ++i) pump(25);
    CHECK(CACHE->pcm(v).frames > 47000 * 3);
    CHECK(CACHE->peaks(v) && CACHE->peaks(v)->count() > 500);
    AudioMixer mix;
    mix.setState(std::make_shared<const ProjectState>(st), 2);
    QVector<float> buf(48000);
    mix.mix(buf.data(), 24000, 12000);
    float pk = 0;
    for (float x : buf) pk = qMax(pk, std::fabs(x));
    printf("mix peak %.3f\n", pk);
    CHECK(pk > .05f && pk < 1.5f);
    {
        ProjectState s3 = st;
        s3.seqs[0].audio[0].muted = true;
        AudioMixer mx2; mx2.setState(std::make_shared<const ProjectState>(s3), 2);
        mx2.mix(buf.data(), 24000, 12000);
        float pk2 = 0;
        for (float x : buf) pk2 = qMax(pk2, std::fabs(x));
        CHECK(pk2 == 0);
        s3.seqs[0].audio[0].muted = false;
        s3.seqs[0].audio[0].clips[0].fx[0].find("level")->value = -6.02;
        AudioMixer mx3; mx3.setState(std::make_shared<const ProjectState>(s3), 2);
        mx3.mix(buf.data(), 24000, 12000);
        float pk3 = 0;
        for (float x : buf) pk3 = qMax(pk3, std::fabs(x));
        CHECK(std::fabs(pk3 / pk - .5f) < .03f);
    }
    // --- all audio effects run without NaN
    for (auto &d : EffectRegistry::all()) {
        if (!d.audio || d.intrinsic) continue;
        ProjectState s3 = st;
        s3.seqs[0].audio[0].clips[0].fx << EffectRegistry::make(d.id);
        AudioMixer mx4; mx4.setState(std::make_shared<const ProjectState>(s3), 2);
        mx4.mix(buf.data(), 24000, 12000);
        for (float x : buf) if (std::isnan(x)) { printf("NaN in %s\n", qPrintable(d.id)); ++fails; break; }
    }

    // --- export: every format end to end
    for (auto &fm : exportFormats()) {
        ExportSettings c;
        c.format = fm.name; c.width = 320; c.height = 180; c.last = 15; c.preset = "ultrafast";
        c.path = dir.filePath("out_" + QString::number(qHash(fm.name)) + "." + fm.ext);
        Exporter ex(st, 2, c);
        QString err; bool ok = false;
        QObject::connect(&ex, &Exporter::failed, [&](const QString &w) { err = w; });
        QObject::connect(&ex, &Exporter::finishedOk, [&](const QString &) { ok = true; });
        ex.start();
        ex.wait();
        pump(5);
        QCoreApplication::processEvents();
        MediaItem o;
        // An image sequence writes numbered files beside the chosen name.
        const QString made = isImageSequence(fm.name) ? QString::asprintf(qPrintable(imageSequencePattern(c.path)), 1) : c.path;
        bool pr = QFileInfo::exists(made) && CACHE->probe(made, o);
        printf("export %-24s %s %s\n", qPrintable(fm.name), pr ? "ok" : "FAILED", qPrintable(err));
        if (!pr) ++fails;
        if (pr && fm.video && fm.name != "Animated GIF" && !isImageSequence(fm.name)) CHECK(o.w == 320 && std::fabs(o.fps - 30) < .1);
        if (pr && isImageSequence(fm.name)) CHECK(o.w == 320 && o.h == 180);
    }
    printf(fails ? "\n%d FAILURES\n" : "\nALL PASSED\n", fails);
    fflush(stdout);
    return fails ? 1 : 0;
}
